from pathlib import Path
p=Path('out/framework/adapters/go/action_validation_test.go');s=p.read_text()
s=s.replace('Nodes: c.Voters, NodesJoint: c.Outgoing','Voters: c.Voters, VotersOutgoing: c.Outgoing').replace('c.Nodes)', 'c.Voters)').replace('c.NodesJoint)', 'c.VotersOutgoing)')
s=s.replace('rn.commitReady(rd)','rn.Advance(rd)').replace('rd = rn.Ready()\n\t\trn.acceptReady(rd)','rd = rn.readyWithoutAccept()\n\t\trn.acceptReady(rd)')
s=s.replace('PreVote                                                           bool','PreVote, CheckQuorum                                              bool')
s=s.replace('Reject                                                  bool','Reject, Forced                                          bool')
s=s.replace('FromID, Context uint64\n}', 'FromID, Context uint64\n\tMessage avMessage\n\tBetween []avMessage\n}')
s=s.replace('func avMsg(m avMessage) pb.Message {\n\treturn', 'func avMsg(m avMessage) pb.Message {\n\tctx := avCtx(m.Context)\n\tif m.Forced { ctx = []byte(campaignTransfer) }\n\treturn').replace('Context: avCtx(m.Context), Entries:', 'Context: ctx, Entries:')
s=s.replace('"context": avCtxID(m.Context),', '"context": avContextID(m.Context), "forced": string(m.Context) == string(campaignTransfer),')
s=s.replace('func avObsMsgs(', 'func avContextID(b []byte) uint64 {\n if string(b) == string(campaignTransfer) { return 0 }; return avCtxID(b)\n}\nfunc avObsMsgs(')
s=s.replace('"preVote": r.preVote,', '"preVote": r.preVote, "checkQuorum": r.checkQuorum,')
s=s.replace('r.preVote = p.PreVote','r.preVote = p.PreVote\n\tr.checkQuorum = p.CheckQuorum')
s=s.replace('rd = rn.Ready()\n\t\tif c.Action == "advance_node" {\n\t\t\trn.acceptReady(rd)\n\t\t}', 'if c.Action == "advance_node" {\n\t\t\trd = rn.readyWithoutAccept(); rn.acceptReady(rd)\n\t\t} else { rd = rn.Ready() }')
s=s.replace('result["captured_ready"] = avRD(rd)', 'result["captured_ready"] = avRD(rd)\n\t\tfor _, m := range c.Input.Between { if e := r.Step(avMsg(m)); e != nil { panic(e) } }')
s=s.replace('"context": c.Input.Context}', '"context": c.Input.Context, "message": avObsMsgs([]pb.Message{avMsg(c.Input.Message)})[0], "between": avObsMessages(c.Input.Between)}\n\tif strings.HasPrefix(c.Action, "advance") { result["input_observation"].(map[string]interface{})["batch"] = avRD(rd) }')
s=s.replace('case "proposal":\n', 'case "vote", "receive":\n\t\terr = rn.Step(avMsg(c.Input.Message))\n\tcase "proposal":\n')
s=s.replace('case "advance_raw":\n\t\trn.Advance(rd)', 'case "advance_raw":\n\t\trn.Advance(rd)\n\t\tret = map[string]interface{}{"batchAfter": avRD(rd)}').replace('case "advance_node":\n\t\trn.Advance(rd)', 'case "advance_node":\n\t\trn.Advance(rd)\n\t\tret = map[string]interface{}{"batchAfter": avRD(rd)}')
s=s.replace('func avObsMsgs(ms', 'func avObsMessages(ms []avMessage) []interface{} {\n out := []pb.Message{}; for _, m := range ms { out = append(out,avMsg(m)) }; return avObsMsgs(out)\n}\nfunc avObsMsgs(ms')
p.write_text(s)
